/* Exam Practice – client. All data comes from bank.js (window.BANK), generated by build/generate.py. */
(function () {
  "use strict";
  const B = window.BANK;
  const app = document.getElementById("app");
  const Q = Object.fromEntries(B.questions.map(q => [q.id, q]));
  const EX = Object.fromEntries(B.exams.map(e => [e.id, e]));
  const RM = Object.fromEntries(B.regression.models.map(m => [m.id, m]));
  const RX = Object.fromEntries(B.regression.exams.map(e => [e.id, e]));

  // ------------------------------------------------------------------ storage (per-viewer convenience)
  const KEY = "exam-practice-v1";
  function load() { try { return JSON.parse(localStorage.getItem(KEY)) || { q: {}, mistakes: [] }; } catch (e) { return { q: {}, mistakes: [] }; } }
  let store = load();
  function save() { try { localStorage.setItem(KEY, JSON.stringify(store)); } catch (e) { /* private mode: keep in memory */ } }
  function rec(id) { return store.q[id] || (store.q[id] = { tries: 0, solved: false, firstTry: false, revealed: false }); }

  // ------------------------------------------------------------------ helpers
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const h = (html) => { const t = document.createElement("template"); t.innerHTML = html.trim(); return t.content; };
  const fmtTime = s => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
  const fmtSize = b => b > 1e6 ? (b / 1e6).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1e3)) + " KB";
  const subjTag = s => `<span class="tag ${s === "Excel" ? "excel" : s === "SQL" ? "sql" : "reg"}">${esc(s)}</span>`;
  const fileLabel = f => B.files[f].label;
  function fmtNum(v) {
    if (Math.abs(v) >= 1000) return v.toLocaleString("en-US", { maximumFractionDigits: 4 });
    return String(+v.toFixed(6));
  }

  /** Parse what a student types: 1,234.56 · 1.234,56 · 1234,5 · $ 3,000 · (1,200) · 7.8% */
  function parseNumber(raw) {
    if (raw == null) return null;
    let s = String(raw).trim();
    if (!s) return null;
    let neg = false, pct = false;
    if (/^\(.*\)$/.test(s)) { neg = true; s = s.slice(1, -1); }
    if (s.endsWith("%")) { pct = true; s = s.slice(0, -1); }
    s = s.replace(/[\s$€£'kr ]/gi, "").replace(/^−/, "-");
    if (s.startsWith("-")) { neg = !neg; s = s.slice(1); }
    const hasC = s.includes(","), hasD = s.includes(".");
    if (hasC && hasD) {
      if (s.lastIndexOf(",") > s.lastIndexOf(".")) s = s.replace(/\./g, "").replace(",", ".");
      else s = s.replace(/,/g, "");
    } else if (hasC) {
      s = /^\d{1,3}(,\d{3})+$/.test(s) ? s.replace(/,/g, "") : s.replace(",", ".");
    } else if (hasD && /^\d{1,3}(\.\d{3}){2,}$/.test(s)) {
      s = s.replace(/\./g, "");
    }
    if (!/^\d*\.?\d+$/.test(s)) return null;
    const v = parseFloat(s) * (neg ? -1 : 1);
    return { v, pct };
  }
  const normText = s => String(s).toLowerCase().replace(/[“”"']/g, "").replace(/\s+/g, " ").trim();

  /** Compare one field. Returns {status: ok|diag|bad|empty|invalid, msg} */
  function checkField(f, raw) {
    if (f.kind === "choice") {
      if (raw == null || raw === "") return { status: "empty" };
      if (raw === f.answer) return { status: "ok" };
      const d = f.diagnostics.find(d => d.value === raw);
      return d ? { status: "diag", msg: d.msg } : { status: "bad" };
    }
    if (f.kind === "text") {
      if (!String(raw || "").trim()) return { status: "empty" };
      if (normText(raw) === normText(f.answer)) return { status: "ok" };
      const d = f.diagnostics.find(d => normText(d.value) === normText(raw));
      return d ? { status: "diag", msg: d.msg } : { status: "bad" };
    }
    const p = parseNumber(raw);
    if (raw == null || String(raw).trim() === "") return { status: "empty" };
    if (!p) return { status: "invalid", msg: "That is not a number I can read. Type digits, for example 1234.56 or 1.234,56." };
    const tol = Math.max(f.tol, 1e-9);
    const cands = f.kind === "percent" ? [p.v / 100, ...(p.pct ? [] : [p.v])] : [p.v];
    const near = (a, b) => Math.abs(a - b) <= tol + 1e-9;
    if (cands.some(c => near(c, f.answer))) return { status: "ok" };
    for (const d of f.diagnostics) if (cands.some(c => near(c, d.value))) return { status: "diag", msg: d.msg };
    // generic diagnosis: sign and unit slips
    const v = cands[0], a = f.answer;
    if (a !== 0) {
      if (near(-v, a)) return { status: "diag", msg: "Right size, wrong sign. Check whether the result should be negative (refunds, credits, differences)." };
      const r = v / a;
      const units = [[1000, "thousand"], [1e6, "million"], [100, "a factor of 100 (percent vs fraction?)"], [24, "a factor of 24 (days vs hours?)"], [60, "a factor of 60 (minutes vs hours/seconds?)"]];
      for (const [k, name] of units) {
        if (Math.abs(r - k) / k < 0.01 || Math.abs(r - 1 / k) * k < 0.01) return { status: "diag", msg: `Your value is off by ${name}. The method is probably right but the unit or scale is not.` };
      }
      const rel = Math.abs(v - a) / Math.abs(a);
      if (rel < 0.02) return { status: "bad", msg: "Very close (within 2%). Check rounding, or a filter that drops or adds a few rows." };
    }
    return { status: "bad" };
  }

  // ------------------------------------------------------------------ answer card (shared by questions and regression)
  function answerBlock(id, fields, solutionHtml, why, onResult) {
    const r = rec(id);
    const wrap = h(`<div class="answer">
      <div class="spread"><h3>Check your result</h3><span class="small muted">${r.solved ? '<span class="tag done">Solved</span>' : r.tries ? `${r.tries} attempt${r.tries > 1 ? "s" : ""}` : ""}</span></div>
      <form class="chk" autocomplete="off">
        <div class="fields">${fields.map((f, i) => fieldHtml(id, f, i)).join("")}</div>
        <div class="row"><button class="btn primary" type="submit">Check</button><span class="small muted">Commas or dots as decimal separator both work.</span></div>
      </form>
      <div class="out" aria-live="polite"></div>
      <details class="sol"><summary>Show model solution</summary><div class="solbody">${solutionHtml}</div></details>
    </div>`);
    const form = wrap.querySelector("form");
    const out = wrap.querySelector(".out");
    const det = wrap.querySelector("details");
    det.addEventListener("toggle", () => { if (det.open && !rec(id).solved) { rec(id).revealed = true; save(); } });
    form.addEventListener("submit", e => {
      e.preventDefault();
      const res = fields.map((f, i) => {
        let raw;
        if (f.kind === "choice") { const c = form.querySelector(`input[name="f${i}"]:checked`); raw = c ? c.value : ""; }
        else raw = form.querySelector(`[name="f${i}"]`).value;
        return { f, i, raw, ...checkField(f, raw) };
      });
      if (res.every(x => x.status === "empty")) { out.innerHTML = `<div class="fb bad">Enter your result first.</div>`; return; }
      const rr = rec(id);
      rr.tries += 1;
      const allOk = res.every(x => x.status === "ok");
      if (allOk && !rr.solved) { rr.solved = true; rr.firstTry = rr.tries === 1 && !rr.revealed; rr.solvedAt = Date.now(); }
      res.filter(x => x.status === "diag").forEach(x => store.mistakes.push({ id, field: x.f.label, msg: x.msg, t: Date.now() }));
      save();
      res.forEach(x => {
        const el = form.querySelector(`[data-field="${x.i}"]`);
        el.classList.remove("ok", "bad");
        if (x.f.kind === "choice") {
          el.querySelectorAll(".choice").forEach(c => c.classList.remove("ok", "bad"));
          const sel = form.querySelector(`input[name="f${x.i}"]:checked`);
          if (sel) sel.closest(".choice").classList.add(x.status === "ok" ? "ok" : "bad");
        } else if (x.status !== "empty") el.classList.add(x.status === "ok" ? "ok" : "bad");
      });
      let html = "";
      if (allOk) {
        html = `<div class="fb ok"><b>Correct.</b> ${rr.tries === 1 ? "First try." : `Solved after ${rr.tries} attempts.`}</div>`;
        if (why) html += `<div class="oral"><b>Examiner follow-up:</b> ${esc(why)} <span class="muted">Answer it out loud before you move on.</span></div>`;
      } else {
        res.forEach(x => {
          if (x.status === "ok") html += `<div class="fb ok"><b>${esc(x.f.label)}:</b> correct.</div>`;
          else if (x.status === "diag") html += `<div class="fb diag"><b>${esc(x.f.label)}: not correct, and the value matches a known mistake.</b><span class="why">${esc(x.msg)}</span></div>`;
          else if (x.status === "invalid") html += `<div class="fb bad"><b>${esc(x.f.label)}:</b> ${esc(x.msg)}</div>`;
          else if (x.status === "empty") html += `<div class="fb bad"><b>${esc(x.f.label)}:</b> missing.</div>`;
          else html += `<div class="fb bad"><b>${esc(x.f.label)}: not the expected result.</b>${x.msg ? `<span class="why">${esc(x.msg)}</span>` : `<span class="why">Re-read every condition in the question (years, filters, &gt; vs &gt;=, which column). The model solution is below if you are stuck.</span>`}</div>`;
        });
      }
      out.innerHTML = html;
      if (onResult) onResult(allOk);
    });
    return wrap;
  }
  function fieldHtml(id, f, i) {
    if (f.kind === "choice") {
      return `<div class="field" data-field="${i}" style="grid-column:1/-1"><label>${esc(f.label)}</label><div class="choices">${f.options.map((o, k) =>
        `<label class="choice"><input type="radio" name="f${i}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join("")}</div></div>`;
    }
    const ph = f.kind === "percent" ? "e.g. 12.34%" : f.kind === "text" ? "type the value" : "number";
    return `<div class="field" data-field="${i}"><label for="${id}-f${i}">${esc(f.label)}</label><input id="${id}-f${i}" name="f${i}" inputmode="${f.kind === "text" ? "text" : "decimal"}" placeholder="${ph}"></div>`;
  }
  function solutionHtml(q) {
    const s = q.solution;
    let html = "";
    if (s.type === "sql") html += `<pre>${esc(s.code)}</pre>`;
    else html += `<ol>${s.steps.map(x => `<li>${esc(x)}</li>`).join("")}</ol>`;
    if (s.note) html += `<p class="small muted">${esc(s.note)}</p>`;
    html += `<p class="small"><b>Accepted answer:</b> ${q.fields.map(f => `${esc(f.label)} = ${esc(f.kind === "number" ? fmtNum(f.answer) : f.kind === "percent" ? (f.answer * 100).toFixed(2) + "%" : f.answer)}`).join(" · ")}</p>`;
    if (q.solution.type === "sql") html += `<p class="small muted">This query was executed on the downloadable database to produce the answer key.</p>`;
    return html;
  }

  // ------------------------------------------------------------------ question card
  function downloadLinks(fileKey) {
    return B.files[fileKey].downloads.map(k => {
      const d = B.downloads[k];
      return `<a class="dl" href="${esc(d.href)}" download><span>${esc(d.name)}</span><span class="muted small">${fmtSize(d.size)}</span></a>`;
    }).join("");
  }
  function questionCard(q, ctx) {
    const F = B.files[q.file];
    const el = h(`<article class="card">
      <div class="meta">${esc(q.subject)} · ${esc(q.id)} · ${esc(F.label)} · ${fmtTime(q.seconds)} estimated</div>
      <p class="prompt">${esc(q.prompt)}</p>
      <div class="note"><div>${esc(F.note)}</div><div class="small" style="margin-top:4px"><code>${esc(F.schema)}</code></div></div>
      ${ctx === "single" ? `<div class="downloads" style="margin-bottom:12px">${downloadLinks(q.file)}</div>` : ""}
      <div class="row small muted">${q.topics.map(t => `<span class="tag">${esc(t)}</span>`).join(" ")}</div>
    </article>`);
    el.querySelector("article").appendChild(answerBlock(q.id, q.fields, solutionHtml(q), q.why, () => { if (ctx && ctx.refresh) ctx.refresh(); }));
    return el;
  }

  // ------------------------------------------------------------------ timer
  function timer(seconds, label) {
    let acc = 0, start = 0, running = false, iv = null;
    const el = h(`<div class="card tight"><div class="timer">
      <div><div class="small muted">Time remaining</div><div class="clock rem">${fmtTime(seconds)}</div></div>
      <div><div class="small muted">Elapsed</div><div class="clock el">0:00</div></div>
      <div class="row"><button class="btn primary small go" type="button">Start timer</button><button class="btn small pause" type="button" disabled>Pause</button><button class="btn small reset" type="button" disabled>Reset</button></div>
    </div><p class="small muted" style="margin:8px 0 0">${esc(label)}</p></div>`);
    const root = el.firstElementChild;
    const rem = root.querySelector(".rem"), ela = root.querySelector(".el");
    const go = root.querySelector(".go"), pause = root.querySelector(".pause"), reset = root.querySelector(".reset");
    const elapsed = () => acc + (running ? (Date.now() - start) / 1000 : 0);
    function tick() {
      const e = elapsed(), r = seconds - e;
      rem.textContent = r >= 0 ? fmtTime(Math.ceil(r)) : "0:00";
      rem.classList.toggle("over", r < 0);
      ela.textContent = fmtTime(e);
      if (r < 0 && !root.dataset.over) { root.dataset.over = "1"; rem.setAttribute("aria-label", "Time is up"); }
    }
    go.onclick = () => { if (running) return; running = true; start = Date.now(); iv = setInterval(tick, 250); go.disabled = true; pause.disabled = false; reset.disabled = false; };
    pause.onclick = () => { if (!running) return; acc = elapsed(); running = false; clearInterval(iv); tick(); go.disabled = false; go.textContent = "Resume"; pause.disabled = true; };
    reset.onclick = () => { acc = 0; running = false; clearInterval(iv); delete root.dataset.over; tick(); go.disabled = false; go.textContent = "Start timer"; pause.disabled = true; reset.disabled = true; };
    root._elapsed = elapsed;
    root._stop = () => clearInterval(iv);
    return root;
  }
  let activeTimer = null;

  // ------------------------------------------------------------------ views
  function viewHome() {
    const s = B.stats;
    const solved = Object.values(store.q).filter(r => r.solved).length;
    app.innerHTML = "";
    app.appendChild(h(`<section class="card hero">
      <h1>Practise the oral exam and check your result</h1>
      <p class="lead">In the oral exam you get one data manipulation exam (Excel + SQL, 8 minutes) and one data interpretation exam (regression output). Every question here has an answer key computed by running code on the same files you download. Type your result to see straight away whether it is right. If it is wrong, the site tells you which mistake produces your number.</p>
      <div class="kpis"><div class="kpi"><b>${s.questions}</b><span>questions</span></div><div class="kpi"><b>${s.exams}</b><span>8-minute exams</span></div><div class="kpi"><b>${s.diagnostics}</b><span>recognised mistakes</span></div><div class="kpi"><b>${s.regressionExams}</b><span>regression exams</span></div><div class="kpi"><b>${solved}</b><span>solved by you</span></div></div>
      <div class="row" style="margin-top:16px"><a class="btn primary" href="#/exam/${randomExam()}">Start a random exam</a><a class="btn" href="#/questions">Browse questions</a><a class="btn" href="#/interpretation">Regression exams</a></div>
    </section>`));
    app.appendChild(h(`<section style="margin-top:18px" class="grid2">
      <div class="card"><h2>1. Do the task in Excel or SQL</h2><p class="muted">Download the file, start the timer and solve the question in the same tool you will use in the exam: Excel, or DB Browser for SQLite.</p></div>
      <div class="card"><h2>2. Type your result</h2><p class="muted">Each question asks for one or two checkpoint values (a count, a total, a name), so a whole table can be checked without uploading it.</p></div>
      <div class="card"><h2>3. Get a diagnosis, not only “wrong”</h2><p class="muted">The course materials warn about specific traps: refunds stored as negative amounts, PreparerID not being unique, job codes after a location suffix, Excel dates stored as days. The checker recognises the number each trap produces.</p></div>
    </section>`));
  }
  function randomExam() {
    const last = sessionGet("lastExam");
    let id;
    do { id = B.exams[Math.floor(Math.random() * B.exams.length)].id; } while (id === last && B.exams.length > 1);
    return id;
  }
  function sessionGet(k) { try { return sessionStorage.getItem(k); } catch (e) { return null; } }
  function sessionSet(k, v) { try { sessionStorage.setItem(k, v); } catch (e) { /* ignore */ } }

  const PAGE = 20;
  function viewExams(params) {
    const page = +(params.get("p") || 0);
    const xf = params.get("excel") || "", sf = params.get("sql") || "";
    const list = B.exams.filter(e => (!xf || e.excel === xf) && (!sf || e.sql === sf));
    const xfs = [...new Set(B.exams.map(e => e.excel))], sfs = [...new Set(B.exams.map(e => e.sql))];
    app.innerHTML = "";
    app.appendChild(h(`<div class="spread"><div><h1>Data manipulation exams</h1><p class="lead">Each exam has three Excel questions and three SQL questions on two data files. You have 8 minutes.</p></div><a class="btn primary" href="#/exam/${randomExam()}">Choose one for me</a></div>`));
    const fl = h(`<div class="filters">
      <label class="f">Excel file<select data-k="excel"><option value="">All Excel files</option>${xfs.map(f => `<option value="${f}" ${f === xf ? "selected" : ""}>${esc(fileLabel(f))}</option>`).join("")}</select></label>
      <label class="f">SQL database<select data-k="sql"><option value="">All databases</option>${sfs.map(f => `<option value="${f}" ${f === sf ? "selected" : ""}>${esc(fileLabel(f))}</option>`).join("")}</select></label>
    </div>`);
    fl.querySelectorAll("select").forEach(s => s.onchange = () => { params.set(s.dataset.k, s.value); params.set("p", 0); go("#/exams?" + params); });
    app.appendChild(fl);
    const ul = document.createElement("div"); ul.className = "list";
    list.slice(page * PAGE, (page + 1) * PAGE).forEach(e => {
      const done = e.questionIds.filter(id => store.q[id] && store.q[id].solved).length;
      ul.appendChild(h(`<a class="item" href="#/exam/${e.id}"><span class="id">${e.id}</span><span class="grow">${esc(fileLabel(e.excel))} + ${esc(fileLabel(e.sql))}</span><span class="tag ${done === 6 ? "done" : ""}">${done}/6 solved</span></a>`));
    });
    app.appendChild(ul);
    app.appendChild(pager(page, Math.ceil(list.length / PAGE), p => { params.set("p", p); go("#/exams?" + params); }));
  }
  function pager(page, pages, to) {
    const el = h(`<div class="pager"><button class="btn small" ${page <= 0 ? "disabled" : ""}>Previous</button><span class="small muted">Page ${pages ? page + 1 : 0} of ${pages}</span><button class="btn small" ${page >= pages - 1 ? "disabled" : ""}>Next</button></div>`);
    const [a, b] = el.querySelectorAll("button");
    a.onclick = () => to(page - 1); b.onclick = () => to(page + 1);
    return el;
  }

  function viewExam(id, qi) {
    const e = EX[id];
    if (!e) return notFound();
    sessionSet("lastExam", id);
    qi = Math.min(Math.max(+qi || 0, 0), e.questionIds.length);
    app.innerHTML = "";
    app.appendChild(h(`<div class="spread"><div><div class="meta">${e.id} · Data manipulation exam · 8 minutes</div><h1>Exam ${e.id}</h1></div><a class="btn ghost" href="#/exams">← All exams</a></div>`));
    app.appendChild(h(`<div class="downloads" style="margin-bottom:12px">${downloadLinks(e.excel)}${downloadLinks(e.sql)}</div>`));
    if (!activeTimer || activeTimer._exam !== id) {
      if (activeTimer) activeTimer._stop();
      activeTimer = timer(e.seconds, "Download and open both files before you start the timer. Importing is part of the timed exam.");
      activeTimer._exam = id;
    }
    app.appendChild(activeTimer);
    const lay = h(`<div class="layout" style="margin-top:14px"><aside class="side"><div class="qnav"></div></aside><div class="body"></div></div>`);
    const nav = lay.querySelector(".qnav"), body = lay.querySelector(".body");
    const status = qid => { const r = store.q[qid]; return !r || !r.tries ? "" : r.solved ? '<span class="st ok">✓</span>' : '<span class="st bad">✗</span>'; };
    function drawNav() {
      nav.innerHTML = e.questionIds.map((qid, k) => `<button class="qbtn ${k === qi ? "on" : ""}" data-k="${k}"><span class="st">${status(qid) || String(k + 1).padStart(2, "0")}</span>${esc(Q[qid].subject)} · ${qid}</button>`).join("")
        + `<button class="qbtn ${qi === e.questionIds.length ? "on" : ""}" data-k="${e.questionIds.length}"><span class="st">Σ</span>Results</button>`;
      nav.querySelectorAll("button").forEach(b => b.onclick = () => go(`#/exam/${id}/${b.dataset.k}`));
    }
    drawNav();
    if (qi < e.questionIds.length) {
      body.appendChild(questionCard(Q[e.questionIds[qi]], { refresh: drawNav }));
      body.appendChild(h(`<div class="spread" style="margin-top:12px"><a class="btn" ${qi === 0 ? 'aria-disabled="true" style="visibility:hidden"' : `href="#/exam/${id}/${qi - 1}"`}>← Previous</a><a class="btn" href="#/exam/${id}/${qi + 1}">${qi === e.questionIds.length - 1 ? "Finish and see results →" : "Next →"}</a></div>`));
    } else {
      body.appendChild(examSummary(e));
    }
    app.appendChild(lay);
  }
  function examSummary(e) {
    const rows = e.questionIds.map(qid => {
      const q = Q[qid], r = store.q[qid] || {};
      const st = r.solved ? (r.firstTry ? "Correct first try" : r.revealed ? "Solved after viewing the solution" : `Solved after ${r.tries} attempts`) : r.tries ? "Not solved yet" : "Not attempted";
      const ms = store.mistakes.filter(m => m.id === qid).map(m => m.msg);
      return `<tr><td>${qid}</td><td>${subjTag(q.subject)}</td><td>${esc(st)}</td><td class="small">${ms.length ? esc(ms[ms.length - 1]) : ""}</td></tr>`;
    }).join("");
    const solved = e.questionIds.filter(qid => store.q[qid] && store.q[qid].solved).length;
    const el = activeTimer && activeTimer._elapsed ? activeTimer._elapsed() : 0;
    return h(`<div class="card"><h2>Results for exam ${e.id}</h2>
      <p>${solved} of ${e.questionIds.length} questions solved${el ? ` · time used ${fmtTime(el)} of 8:00` : ""}.</p>
      <div class="tablewrap"><table class="summary"><thead><tr><th>Question</th><th>Subject</th><th>Status</th><th>Last diagnosed mistake</th></tr></thead><tbody>${rows}</tbody></table></div>
      <div class="row" style="margin-top:12px"><a class="btn primary" href="#/exam/${randomExam()}">Try another exam</a><a class="btn" href="#/progress">See all my mistakes</a></div></div>`);
  }

  function viewQuestions(params) {
    const page = +(params.get("p") || 0);
    const subj = params.get("s") || "", file = params.get("f") || "", topic = params.get("t") || "", text = (params.get("q") || "").toLowerCase(), state = params.get("st") || "";
    const files = Object.keys(B.files).filter(f => B.files[f].subject !== "Regression" && (!subj || B.files[f].subject === subj));
    const topics = [...new Set(B.questions.flatMap(q => q.topics))].sort();
    const list = B.questions.filter(q => (!subj || q.subject === subj) && (!file || q.file === file) && (!topic || q.topics.includes(topic)) && (!text || q.prompt.toLowerCase().includes(text))
      && (!state || (state === "todo" ? !(store.q[q.id] && store.q[q.id].solved) : state === "done" ? store.q[q.id] && store.q[q.id].solved : store.mistakes.some(m => m.id === q.id))));
    app.innerHTML = "";
    app.appendChild(h(`<h1>Question bank</h1><p class="lead">${B.questions.length} Excel and SQL questions. Every exam is built from these questions.</p>`));
    const fl = h(`<div class="filters">
      <label class="f">Subject<select data-k="s"><option value="">All subjects</option><option ${subj === "Excel" ? "selected" : ""}>Excel</option><option ${subj === "SQL" ? "selected" : ""}>SQL</option></select></label>
      <label class="f">File<select data-k="f"><option value="">All files</option>${files.map(f => `<option value="${f}" ${f === file ? "selected" : ""}>${esc(fileLabel(f))}</option>`).join("")}</select></label>
      <label class="f">Skill<select data-k="t"><option value="">All skills</option>${topics.map(t => `<option ${t === topic ? "selected" : ""}>${esc(t)}</option>`).join("")}</select></label>
      <label class="f">Status<select data-k="st"><option value="">All</option><option value="todo" ${state === "todo" ? "selected" : ""}>Not solved</option><option value="done" ${state === "done" ? "selected" : ""}>Solved</option><option value="mist" ${state === "mist" ? "selected" : ""}>I made a known mistake</option></select></label>
      <label class="f">Search<input data-k="q" value="${esc(params.get("q") || "")}" placeholder="e.g. refunds"></label>
    </div>`);
    fl.querySelectorAll("select").forEach(s => s.onchange = () => { params.set(s.dataset.k, s.value); if (s.dataset.k === "s") params.delete("f"); params.set("p", 0); go("#/questions?" + params); });
    const inp = fl.querySelector("input");
    inp.onkeydown = ev => { if (ev.key === "Enter") { params.set("q", inp.value); params.set("p", 0); go("#/questions?" + params); } };
    app.appendChild(fl);
    app.appendChild(h(`<p class="small muted">${list.length} question${list.length === 1 ? "" : "s"}</p>`));
    const ul = document.createElement("div"); ul.className = "list";
    list.slice(page * PAGE, (page + 1) * PAGE).forEach(q => {
      const r = store.q[q.id];
      ul.appendChild(h(`<a class="item" href="#/q/${q.id}"><span class="id">${q.id}</span><span class="grow">${esc(q.prompt)}<br><span class="small muted">${esc(fileLabel(q.file))} · ${q.topics.map(esc).join(", ")}</span></span>${subjTag(q.subject)}${r && r.solved ? '<span class="tag done">✓</span>' : r && r.tries ? '<span class="tag miss">✗</span>' : ""}</a>`));
    });
    if (!list.length) ul.appendChild(h(`<div class="empty">No questions match. Try another filter.</div>`));
    app.appendChild(ul);
    app.appendChild(pager(page, Math.ceil(list.length / PAGE), p => { params.set("p", p); go("#/questions?" + params); }));
  }
  function viewQuestion(id) {
    const q = Q[id];
    if (!q) return notFound();
    const sameFile = B.questions.filter(x => x.file === q.file);
    const k = sameFile.indexOf(q);
    app.innerHTML = "";
    app.appendChild(h(`<div class="spread" style="margin-bottom:10px"><a class="btn ghost" href="#/questions">← Question bank</a><div class="row">${k > 0 ? `<a class="btn small" href="#/q/${sameFile[k - 1].id}">← Previous in file</a>` : ""}${k < sameFile.length - 1 ? `<a class="btn small" href="#/q/${sameFile[k + 1].id}">Next in file →</a>` : ""}</div></div>`));
    app.appendChild(questionCard(q, "single"));
  }

  // ------------------------------------------------------------------ regression
  function viewInterpretation() {
    app.innerHTML = "";
    app.appendChild(h(`<div class="spread"><div><h1>Data interpretation exams</h1><p class="lead">Each exam shows regression output estimated on the restaurant case (Larry’s Commissary, 2018) and asks four questions: a prediction, significance, interpretation of a coefficient and R². You have 5 minutes.</p></div><a class="btn primary" href="#/ie/${B.regression.exams[Math.floor(Math.random() * B.regression.exams.length)].id}">Choose one for me</a></div>`));
    const ul = document.createElement("div"); ul.className = "list";
    B.regression.exams.forEach(e => {
      const m = RM[e.model];
      const done = e.questions.filter((_, k) => store.q[`${e.id}-${k}`] && store.q[`${e.id}-${k}`].solved).length;
      ul.appendChild(h(`<a class="item" href="#/ie/${e.id}"><span class="id">${e.id}</span><span class="grow">${esc(m.title)}<br><span class="small muted">${esc(m.y)} · ${m.coefs.length - 1} predictor${m.coefs.length > 2 ? "s" : ""}</span></span><span class="tag ${done === 4 ? "done" : ""}">${done}/4</span></a>`));
    });
    app.appendChild(ul);
  }
  function viewRegExam(id, qi) {
    const e = RX[id];
    if (!e) return notFound();
    const m = RM[e.model];
    qi = Math.min(Math.max(+qi || 0, 0), e.questions.length - 1);
    app.innerHTML = "";
    app.appendChild(h(`<div class="spread"><div><div class="meta">${e.id} · Data interpretation exam · 5 minutes</div><h1>${esc(m.title)}</h1></div><a class="btn ghost" href="#/interpretation">← All regression exams</a></div>`));
    if (!activeTimer || activeTimer._exam !== id) {
      if (activeTimer) activeTimer._stop();
      activeTimer = timer(e.seconds, "Read the output, then answer all four questions.");
      activeTimer._exam = id;
    }
    app.appendChild(activeTimer);
    const out = h(`<div class="card" style="margin-top:14px">
      <div class="spread"><h2 style="margin:0">Regression output</h2><a class="dl" style="width:auto" href="${esc(B.downloads.rest.href)}" download>${esc(B.downloads.rest.name)} <span class="muted small">${fmtSize(B.downloads.rest.size)}</span></a></div>
      <p class="small muted" style="margin-top:8px">Dependent variable: ${esc(m.y)} · Observations: ${m.n} · R² = ${m.r2.toFixed(3)}</p>
      <div class="tablewrap"><table class="coef"><thead><tr><th>Variable</th><th>Coefficient</th><th>Std. error</th><th>t</th><th>p-value</th></tr></thead><tbody>
      ${m.coefs.map(c => `<tr><td>${esc(c.label)}</td><td>${fmtNum(c.b)}</td><td>${fmtNum(c.se)}</td><td>${c.t.toFixed(2)}</td><td>${c.p < 0.001 ? "&lt;0.001" : c.p.toFixed(3)}</td></tr>`).join("")}
      </tbody></table></div></div>`);
    app.appendChild(out);
    const lay = h(`<div class="layout" style="margin-top:14px"><aside class="side"><div class="qnav"></div></aside><div class="body"></div></div>`);
    const nav = lay.querySelector(".qnav"), body = lay.querySelector(".body");
    const names = { predict: "Prediction", significance: "Significance", interpret: "Interpretation", r2: "R²" };
    function drawNav() {
      nav.innerHTML = e.questions.map((q, k) => { const r = store.q[`${id}-${k}`]; const st = !r || !r.tries ? String(k + 1).padStart(2, "0") : r.solved ? '<span class="st ok">✓</span>' : '<span class="st bad">✗</span>'; return `<button class="qbtn ${k === qi ? "on" : ""}" data-k="${k}"><span class="st">${st}</span>${names[q.kind]}</button>`; }).join("");
      nav.querySelectorAll("button").forEach(b => b.onclick = () => go(`#/ie/${id}/${b.dataset.k}`));
    }
    drawNav();
    const q = e.questions[qi];
    const card = h(`<article class="card"><div class="meta">Question ${qi + 1} of 4 · ${names[q.kind]}</div><p class="prompt">${esc(q.prompt)}</p></article>`);
    card.querySelector("article").appendChild(answerBlock(`${id}-${qi}`, q.fields, `<p>${esc(q.solution)}</p>`, null, drawNav));
    body.appendChild(card);
    body.appendChild(h(`<div class="spread" style="margin-top:12px">${qi > 0 ? `<a class="btn" href="#/ie/${id}/${qi - 1}">← Previous</a>` : "<span></span>"}${qi < 3 ? `<a class="btn" href="#/ie/${id}/${qi + 1}">Next →</a>` : `<a class="btn primary" href="#/interpretation">Done</a>`}</div>`));
    app.appendChild(lay);
  }

  // ------------------------------------------------------------------ progress / mistake log
  function viewProgress() {
    app.innerHTML = "";
    const qs = Object.entries(store.q).filter(([id]) => Q[id]);
    const tried = qs.filter(([, r]) => r.tries), solved = qs.filter(([, r]) => r.solved), first = qs.filter(([, r]) => r.firstTry);
    app.appendChild(h(`<h1>My mistakes</h1><p class="lead">Saved only in this browser. The mistakes the checker recognised are grouped below, so you can see which traps you fall into again and again.</p>`));
    app.appendChild(h(`<div class="card"><div class="kpis"><div class="kpi"><b>${tried.length}</b><span>questions attempted</span></div><div class="kpi"><b>${solved.length}</b><span>solved</span></div><div class="kpi"><b>${first.length}</b><span>correct on first try</span></div><div class="kpi"><b>${store.mistakes.length}</b><span>recognised mistakes</span></div></div></div>`));
    // by skill
    const topics = {};
    tried.forEach(([id, r]) => Q[id].topics.forEach(t => { const o = topics[t] || (topics[t] = { n: 0, first: 0 }); o.n++; if (r.firstTry) o.first++; }));
    const tl = Object.entries(topics).sort((a, b) => a[1].first / a[1].n - b[1].first / b[1].n);
    app.appendChild(h(`<div class="card" style="margin-top:14px"><h2>First-try accuracy by skill</h2>${tl.length ? tl.map(([t, o]) => `<div style="margin:8px 0"><div class="spread small"><a href="#/questions?t=${encodeURIComponent(t)}&st=todo">${esc(t)}</a><span class="muted">${o.first}/${o.n}</span></div><div class="bar"><i style="width:${Math.round(100 * o.first / o.n)}%"></i></div></div>`).join("") : `<div class="empty">Attempt a few questions to see your accuracy by skill.</div>`}</div>`));
    // recurring mistakes
    const grp = {};
    store.mistakes.forEach(m => { const g = grp[m.msg] || (grp[m.msg] = { n: 0, ids: new Set() }); g.n++; g.ids.add(m.id); });
    const gl = Object.entries(grp).sort((a, b) => b[1].n - a[1].n);
    app.appendChild(h(`<div class="card" style="margin-top:14px"><h2>Recurring mistakes</h2>${gl.length ? `<div class="list">${gl.map(([msg, g]) => `<div class="item"><span class="tag miss">${g.n}×</span><span class="grow">${esc(msg)}<br><span class="small muted">${[...g.ids].filter(id => Q[id]).map(id => `<a href="#/q/${id}">${id}</a>`).join(", ")}</span></span></div>`).join("")}</div>` : `<div class="empty">No recognised mistakes yet.</div>`}</div>`));
    const reset = h(`<p style="margin-top:14px"><button class="btn small">Clear my progress</button></p>`);
    reset.querySelector("button").onclick = () => { if (confirm("Clear all saved attempts in this browser?")) { store = { q: {}, mistakes: [] }; save(); viewProgress(); } };
    app.appendChild(reset);
  }

  function notFound() { app.innerHTML = `<div class="empty">That page does not exist. <a href="#/">Go to the start page</a>.</div>`; }

  // ------------------------------------------------------------------ router
  function go(hash) { if (location.hash === hash) route(); else location.hash = hash; }
  function route() {
    const raw = location.hash.replace(/^#/, "") || "/";
    const [path, qs] = raw.split("?");
    const params = new URLSearchParams(qs || "");
    const parts = path.split("/").filter(Boolean);
    const sec = parts[0] || "";
    document.querySelectorAll("[data-nav]").forEach(a => a.classList.toggle("active",
      a.dataset.nav === sec || (a.dataset.nav === "exams" && sec === "exam") || (a.dataset.nav === "questions" && sec === "q") || (a.dataset.nav === "interpretation" && sec === "ie")));
    if (sec !== "exam" && sec !== "ie" && activeTimer) { activeTimer._stop(); activeTimer = null; }
    if (!sec) viewHome();
    else if (sec === "exams") viewExams(params);
    else if (sec === "exam") viewExam(parts[1], parts[2]);
    else if (sec === "questions") viewQuestions(params);
    else if (sec === "q") viewQuestion(parts[1]);
    else if (sec === "interpretation") viewInterpretation();
    else if (sec === "ie") viewRegExam(parts[1], parts[2]);
    else if (sec === "progress") viewProgress();
    else notFound();
    const t = { "": "Exam Practice", exams: "Exams", exam: `Exam ${parts[1] || ""}`, questions: "Question bank", q: `Question ${parts[1] || ""}`, interpretation: "Regression exams", ie: `Regression ${parts[1] || ""}`, progress: "My mistakes" }[sec];
    document.title = `${t || "Exam Practice"} · Data Analytics in Accounting`;
    if (!(sec === "exam" || sec === "ie") || !parts[2]) window.scrollTo(0, 0);
  }
  window.__examPractice = { checkField, parseNumber }; // used by the self-test in the README
  window.addEventListener("hashchange", route);
  route();
})();
